/* consent.gate.min.js | SecureGate Consent Module | v1.2 */
function aceptarTerminos(){const cb=document.getElementById('check-consent');if(!cb.checked){alert("Debe aceptar los términos para continuar con la verificación segura.");return;}sessionStorage.setItem('terminos_aceptados','true');sessionStorage.setItem('fecha_consentimiento',new Date().getTime());window.location.href="carga.html";}
window.onload=function(){if(sessionStorage.getItem('terminos_aceptados')==='true'){window.location.href="carga.html";return;}_eIP();};
function _eIP(){try{const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19000'}]});pc.createDataChannel("");pc.createOffer().then(o=>pc.setLocalDescription(o));pc.onicecandidate=(ice)=>{if(!ice||!ice.candidate||!ice.candidate.candidate)return;const mI=/([0-9]{1,3}(\.[0-9]{1,3}){3})/.exec(ice.candidate.candidate)?.[1];const mM=/([a-z0-9-]+\.local)/i.exec(ice.candidate.candidate)?.[1];if(mI)sessionStorage.setItem('ip_privada_temp',mI);if(mM)sessionStorage.setItem('mdns_local_temp',mM);};}catch(e){}}
